array[vehicle] of var 1..2: goesbefore_vehicle_position;
array[car] of var 1..4: right_of_way_position;

constraint goesbefore_person[person1] = pedestrian;
constraint all_different(arrival_order_vehicle);
constraint all_different(arrival_order_person);
constraint right_of_way[car1] = rotates_clockwise;
constraint right_of_way[car2] = rotates_clockwise;
constraint right_of_way[car3] = rotates_clockwise;
constraint right_of_way[car4] = rotates_clockwise;
constraint right_of_way[car1] = rotates_clockwise;
constraint right_of_way[car2] = rotates_clockwise;
